import pandas as pd
import json
import math

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Sale_Date'] = pd.to_datetime(df['Sale_Date'])
df['Year'] = df['Sale_Date'].dt.year
df['Month'] = df['Sale_Date'].dt.month
df['YearMonth'] = df['Sale_Date'].dt.to_period('M').astype(str)

# ── KPI Calculations ──
total_transactions = len(df)
avg_profit_margin = df['Profit_Margin_USD'].mean()
resale_premium_rate = (df['Resale_Price_USD'] > df['Retail_Price_USD']).mean() * 100
avg_days_inventory = df['Days_in_Inventory'].mean()
avg_resale_retail_ratio = (df['Resale_Price_USD'] / df['Retail_Price_USD']).mean()

# Top colorway margin
colorway_margins = df.groupby('Colorway')['Profit_Margin_USD'].mean()
top_colorway = colorway_margins.idxmax()
top_colorway_margin = colorway_margins.max()

# Date range
date_min = df['Sale_Date'].min().strftime('%Y-%m-%d')
date_max = df['Sale_Date'].max().strftime('%Y-%m-%d')

# ── Section 1: Market Overview ──
avg_retail = df['Retail_Price_USD'].mean()
avg_resale = df['Resale_Price_USD'].mean()
median_profit = df['Profit_Margin_USD'].median()
profit_positive = (df['Profit_Margin_USD'] > 0).sum()
profit_negative = (df['Profit_Margin_USD'] <= 0).sum()
profit_margin_std = df['Profit_Margin_USD'].std()

# Profit margin distribution buckets
bins = [-200, -100, -50, 0, 50, 100, 200, 500, 1000]
labels = ['< -$100', '-$100 to -$50', '-$50 to $0', '$0 to $50', '$50 to $100', '$100 to $200', '$200 to $500', '$500+']
margin_dist = pd.cut(df['Profit_Margin_USD'], bins=bins, labels=labels, right=False)
margin_counts = margin_dist.value_counts().sort_index()

# ── Section 2: Model & Colorway Analysis ──
model_stats = df.groupby('Shoe_Model').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    median_margin=('Profit_Margin_USD', 'median'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100),
    avg_ratio=('Resale_Price_USD', lambda x: (x / df.loc[x.index, 'Retail_Price_USD']).mean())
).sort_values('avg_margin', ascending=False)
model_stats = model_stats.round(2)

colorway_stats = df.groupby(['Shoe_Model', 'Colorway']).agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100)
).sort_values('avg_margin', ascending=False)
colorway_stats = colorway_stats.round(2)

# Below-retail segments
below_retail = df[df['Profit_Margin_USD'] <= 0].groupby(['Shoe_Model', 'Colorway']).size().reset_index(name='below_retail_count')
total_by_combo = df.groupby(['Shoe_Model', 'Colorway']).size().reset_index(name='total_count')
below_retail_merged = below_retail.merge(total_by_combo, on=['Shoe_Model', 'Colorway'])
below_retail_merged['below_rate'] = (below_retail_merged['below_retail_count'] / below_retail_merged['total_count'] * 100).round(1)
below_retail_merged = below_retail_merged.sort_values('below_rate', ascending=False)

# ── Section 3: Condition Impact ──
condition_stats = df.groupby('Condition').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    median_margin=('Profit_Margin_USD', 'median'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100),
    avg_ratio=('Resale_Price_USD', lambda x: (x / df.loc[x.index, 'Retail_Price_USD']).mean()),
    avg_days=('Days_in_Inventory', 'mean')
).round(2)

# Condition premium gap
ds_margin = condition_stats.loc['Deadstock (Brand New)', 'avg_margin'] if 'Deadstock (Brand New)' in condition_stats.index else 0
vnds_margin = condition_stats.loc['VNDS (Very Near Deadstock)', 'avg_margin'] if 'VNDS (Very Near Deadstock)' in condition_stats.index else 0
used_margin = condition_stats.loc['Used', 'avg_margin'] if 'Used' in condition_stats.index else 0
ds_vnds_gap = ds_margin - vnds_margin
vnds_used_gap = vnds_margin - used_margin
ds_used_gap = ds_margin - used_margin

# Condition by model
condition_model = df.groupby(['Shoe_Model', 'Condition'])['Profit_Margin_USD'].mean().unstack(fill_value=0).round(2)

# ── Section 4: Channel Performance ──
channel_stats = df.groupby('Sales_Channel').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    median_margin=('Profit_Margin_USD', 'median'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100),
    avg_days=('Days_in_Inventory', 'mean'),
    avg_ratio=('Resale_Price_USD', lambda x: (x / df.loc[x.index, 'Retail_Price_USD']).mean())
).round(2).sort_values('avg_margin', ascending=False)

# Channel velocity vs margin scatter data
channel_scatter = channel_stats[['avg_margin', 'avg_days', 'count']].reset_index()
channel_scatter_data = []
for _, row in channel_scatter.iterrows():
    channel_scatter_data.append({
        'channel': row['Sales_Channel'],
        'margin': row['avg_margin'],
        'days': row['avg_days'],
        'count': int(row['count'])
    })

# ── Section 5: Temporal Trends ──
monthly_trends = df.groupby('YearMonth').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    count=('Transaction_ID', 'count'),
    avg_days=('Days_in_Inventory', 'mean')
).reset_index()
monthly_trends = monthly_trends.sort_values('YearMonth')

yearly_trends = df.groupby('Year').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_margin=('Profit_Margin_USD', 'mean'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100),
    avg_days=('Days_in_Inventory', 'mean')
).round(2)

# Seasonality by month
month_seasonality = df.groupby('Month').agg(
    avg_margin=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    count=('Transaction_ID', 'count'),
    premium_rate=('Profit_Margin_USD', lambda x: (x > 0).mean() * 100)
).round(2)

# ── Build JSON data for charts ──
chart_data = {
    'margin_dist': {
        'labels': list(margin_counts.index.astype(str)),
        'values': [int(v) for v in margin_counts.values]
    },
    'model_margins': {
        'labels': list(model_stats.index),
        'margins': [float(v) for v in model_stats['avg_margin'].values],
        'premium_rates': [float(v) for v in model_stats['premium_rate'].values],
        'counts': [int(v) for v in model_stats['count'].values]
    },
    'condition_comparison': {
        'labels': [str(l) for l in condition_stats.index],
        'margins': [float(v) for v in condition_stats['avg_margin'].values],
        'premium_rates': [float(v) for v in condition_stats['premium_rate'].values],
        'avg_ratios': [float(v) for v in condition_stats['avg_ratio'].values],
        'counts': [int(v) for v in condition_stats['count'].values]
    },
    'channel_performance': {
        'labels': list(channel_stats.index),
        'margins': [float(v) for v in channel_stats['avg_margin'].values],
        'days': [float(v) for v in channel_stats['avg_days'].values],
        'premium_rates': [float(v) for v in channel_stats['premium_rate'].values],
        'counts': [int(v) for v in channel_stats['count'].values],
        'avg_ratios': [float(v) for v in channel_stats['avg_ratio'].values]
    },
    'channel_scatter': channel_scatter_data,
    'monthly_trends': {
        'labels': list(monthly_trends['YearMonth'].values),
        'margins': [float(v) for v in monthly_trends['avg_margin'].values],
        'counts': [int(v) for v in monthly_trends['count'].values],
        'avg_days': [float(v) for v in monthly_trends['avg_days'].values]
    },
    'yearly_trends': {
        'labels': [str(int(y)) for y in yearly_trends.index],
        'margins': [float(v) for v in yearly_trends['avg_margin'].values],
        'premium_rates': [float(v) for v in yearly_trends['premium_rate'].values],
        'counts': [int(v) for v in yearly_trends['count'].values],
        'avg_days': [float(v) for v in yearly_trends['avg_days'].values]
    },
    'month_seasonality': {
        'labels': ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
        'margins': [float(v) for v in month_seasonality['avg_margin'].values],
        'premium_rates': [float(v) for v in month_seasonality['premium_rate'].values],
        'counts': [int(v) for v in month_seasonality['count'].values]
    }
}

# Colorway top/bottom
top10_colorways = colorway_stats.head(10).reset_index()
bottom10_colorways = colorway_stats.tail(10).reset_index()

# Condition model heatmap data
condition_model_data = {}
for model in condition_model.index:
    condition_model_data[model] = {}
    for cond in condition_model.columns:
        condition_model_data[model][cond] = float(condition_model.loc[model, cond])

chart_data['condition_model'] = condition_model_data

# Below-retail top segments
below_retail_top = below_retail_merged.head(10)

# ── Helper to format numbers ──
def fmt(val, decimals=2):
    if isinstance(val, float):
        if math.isnan(val):
            return 'N/A'
        return f'{val:,.{decimals}f}'
    return str(val)

def fmt_dollar(val):
    if isinstance(val, float) and math.isnan(val):
        return 'N/A'
    return f'${val:,.2f}'

def fmt_pct(val):
    if isinstance(val, float) and math.isnan(val):
        return 'N/A'
    return f'{val:.1f}%'

def fmt_int(val):
    return f'{int(val):,}'

# ── Build HTML ──
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #242836;
    --border: #2e3344;
    --text: #e4e6ed;
    --text2: #9ca0ad;
    --accent: #3b82f6;
    --accent2: #6366f1;
    --green: #22c55e;
    --red: #ef4444;
    --amber: #f59e0b;
    --teal: #14b8a6;
  }}
  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg); color: var(--text);
    line-height: 1.6; padding: 0;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 40px 24px; }}
  .header {{
    text-align: center; padding: 60px 24px 40px;
    background: linear-gradient(135deg, #1a1d27 0%, #0f1117 50%, #1a1d27 100%);
    border-bottom: 1px solid var(--border);
  }}
  .header h1 {{
    font-size: 2.4rem; font-weight: 700;
    background: linear-gradient(135deg, #3b82f6, #6366f1, #8b5cf6);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    margin-bottom: 8px;
  }}
  .header p {{ color: var(--text2); font-size: 1.1rem; }}
  .header .meta {{ color: var(--text2); font-size: 0.85rem; margin-top: 12px; }}
  .kpi-grid {{
    display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px; margin: 32px 0;
  }}
  .kpi-card {{
    background: var(--surface); border: 1px solid var(--border);
    border-radius: 12px; padding: 24px; text-align: center;
  }}
  .kpi-card .value {{
    font-size: 2rem; font-weight: 700; margin-bottom: 4px;
  }}
  .kpi-card .value.green {{ color: var(--green); }}
  .kpi-card .value.amber {{ color: var(--amber); }}
  .kpi-card .value.blue {{ color: var(--accent); }}
