best_ch_velocity_val = channel_stats.loc[best_ch_velocity, 'avg_days']

# Annualized return calculation for top channels
def annualized_return(margin, days):
    if days <= 0:
        return 0
    return margin * (365 / days)

ch_annualized = {}
for ch in channel_stats.index:
    ar = annualized_return(channel_stats.loc[ch, 'avg_margin'], channel_stats.loc[ch, 'avg_days'])
    ch_annualized[ch] = ar

