# ── Helper to format numbers ──
def fmt(val, decimals=2):
    if isinstance(val, float):
        if math.isnan(val):
            return 'N/A'
        return f'{val:,.{decimals}f}'
    return str(val)

def fmt_dollar(val):
    if isinstance(val, float) and math.isnan(val):
        return 'N/A'
    return f'${val:,.2f}'

def fmt_pct(val):
    if isinstance(val, float) and math.isnan(val):
        return 'N/A'
    return f'{val:.1f}%'

def fmt_int(val):
    return f'{int(val):,}'

