<div class="section">
  <h2>6. Key Findings & Strategic Recommendations</h2>
  <p class="section-desc">Synthesizing insights into actionable recommendations for resellers regarding model selection, optimal sales channels, inventory holding periods, and timing strategies.</p>
'''

# Build recommendations based on data
top_model = model_stats.index[0]
top_model_margin = model_stats.iloc[0]['avg_margin']
